const express = require('express');
const Stripe = require('stripe');
const db = require('../db');

const app = express();
app.use(express.json());
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

app.post('/api/vendors/onboarding-link', async (req, res) => {
  const { targetAccountId } = req.body;

  if (!targetAccountId) {
    return res.status(400).json({ error: 'targetAccountId is required' });
  }

  // Ensure the target account belongs to the authenticated vendor
  const vendor = await db('registered_vendors')
    .where({ stripe_connected_id: targetAccountId, user_id: req.user.id })
    .first();
  if (!vendor) {
    return res.status(403).json({ error: 'Unauthorized to generate onboarding link for this account' });
  }

  try {
    const accountLink = await stripe.accountLinks.create({
      account: targetAccountId,
      refresh_url: 'https://platform.com/onboarding/refresh',
      return_url: 'https://platform.com/onboarding/complete',
      type: 'account_onboarding'
    });

    return res.json({ url: accountLink.url });
  } catch (err) {
    return res.status(500).json({ error: 'Failed to generate onboarding link' });
  }
});

module.exports = app;
